{
  "judgments": [
    {
      "proposal_id": "P0000",
      "quotes": [
        "Applications received without photographs:",
        "Passport specialists must suspend a form DS-11 received without a photograph from an acceptance facility. The applicant must re-execute the form DS-11 (see IRL 975-04);"
      ],
      "rationale": "P0000 targets C0031 ('The applicant must re-execute the form DS-11') as one of the rules qualified by the general heading 'Applications received without photographs:'. However, re-execution of Form DS-11 is not a duty applying generally across all applications received without photographs (for instance, a Form DS-82 received without a photo is suspended under IRL 1000-05, and Form DS-11 presented at a public counter without a photo is refused under item (2)). Re-execution under C0031 is conditioned specifically on Form DS-11 being received without a photograph from an acceptance facility and suspended under item (3). Conditioning C0031 under a blanket condition of applications received without photographs incorrectly admits non-acceptance facility and non-DS-11 applications to the re-execution duty.",
      "verdict": "unsupported"
    },
    {
      "proposal_id": "P0001",
      "quotes": [
        "The applicant’s expression should be natural.",
        "Applicants with physical or mental disabilities, including loss of muscle control (e.g., age-related degeneration or because of a medical condition such as Bell's Palsy), may not be able to produce a natural or unexaggerated expression. You may accept a photograph without a natural or unexaggerated expression in these circumstances."
      ],
      "rationale": "The source supports that while an applicant's expression should be natural (C0022), adjudicators are permitted to accept photographs lacking a natural or unexaggerated expression when physical or mental disabilities prevent it. Adding this qualification creates an explicit exception edge qualifying baseline recommendation C0022 without misrepresenting modal force or asserting an absence of legal duty.",
      "verdict": "supported"
    },
    {
      "proposal_id": "P0002",
      "quotes": [
        "Both of the applicant’s eyes should also be visible and open in the photograph (see the exception for infants in 8 FAM 402.1-1).",
        "If the applicant is unable to open one or both eyes because of a medical condition, you may accept the photograph."
      ],
      "rationale": "The source directly qualifies the baseline standard that both eyes should be visible and open (C0025) with an express exception permitting adjudicators to accept the photograph if the applicant cannot open one or both eyes due to a medical condition. P0002 faithfully establishes this qualification relationship with the correct target baseline, scope, and modal force.",
      "verdict": "supported"
    }
  ]
}
